import React, { useState } from "react";
import { View, Text, TextInput, TouchableOpacity, StyleSheet } from "react-native";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

export default function App() {
  const [peso, setPeso] = useState("");
  const [altura, setAltura] = useState("");
  const [imc, setImc] = useState(null);
  const [categoria, setCategoria] = useState("");
  const [dica, setDica] = useState("");

  const calcularIMC = () => {
    const pesoNum = parseFloat(peso.replace(",", "."));
    const alturaNum = parseFloat(altura.replace(",", ".")) / 100;

    // ⚠️ Verificações e toasts
    if (!peso || !altura) {
      toast.warn("Por favor, preencha todos os campos.");
      return;
    }

    if (isNaN(pesoNum) || isNaN(alturaNum)) {
      toast.error("Insira apenas números válidos!");
      return;
    }

    if (pesoNum <= 0 || alturaNum <= 0) {
      toast.error("Os valores devem ser maiores que zero.");
      return;
    }

    if (alturaNum < 0.5 || alturaNum > 2.5) {
      toast.warn("Altura fora do intervalo esperado (em metros).");
      return;
    }

    if (pesoNum < 10 || pesoNum > 400) {
      toast.warn("Peso fora do intervalo esperado (em kg).");
      return;
    }

    // ✅ Cálculo do IMC
    const valorIMC = pesoNum / (alturaNum * alturaNum);
    const imcFormatado = valorIMC.toFixed(2);
    setImc(imcFormatado);

    if (valorIMC < 18.5) {
      setCategoria("Abaixo do peso");
      setDica("Tente manter uma alimentação equilibrada e consulte um nutricionista.");
    } else if (valorIMC < 24.9) {
      setCategoria("Peso normal");
      setDica("Continue com seus hábitos saudáveis!");
    } else if (valorIMC < 29.9) {
      setCategoria("Sobrepeso");
      setDica("Equilibre alimentação e atividade física.");
    } else {
      setCategoria("Obesidade");
      setDica("Busque acompanhamento médico e nutricional.");
    }

    toast.success("IMC calculado com sucesso!");
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Calculadora de IMC</Text>

      <TextInput
        style={styles.input}
        placeholder="Peso (kg)"
        keyboardType="numeric"
        value={peso}
        onChangeText={setPeso}
      />

      <TextInput
        style={styles.input}
        placeholder="Altura (cm)"
        keyboardType="numeric"
        value={altura}
        onChangeText={setAltura}
      />

      <TouchableOpacity style={styles.button} onPress={calcularIMC}>
        <Text style={styles.buttonText}>Calcular</Text>
      </TouchableOpacity>

      {imc && (
        <View style={styles.resultContainer}>
          <Text style={styles.result}>Seu IMC: {imc}</Text>
          <Text style={styles.category}>{categoria}</Text>
          <Text style={styles.dica}>{dica}</Text>
        </View>
      )}

      {/* 🟢 Container global do Toast */}
      <ToastContainer position="top-right" autoClose={4000} theme="colored" />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "#F9FAFB",
    padding: 20,
  },
  title: {
    fontSize: 26,
    fontWeight: "bold",
    marginBottom: 20,
    color: "#1E293B",
  },
  input: {
    width: "80%",
    borderWidth: 1,
    borderColor: "#CBD5E1",
    borderRadius: 10,
    padding: 12,
    marginBottom: 10,
    backgroundColor: "#FFF",
  },
  button: {
    backgroundColor: "#2563EB",
    paddingVertical: 12,
    paddingHorizontal: 40,
    borderRadius: 10,
    marginTop: 5,
  },
  buttonText: {
    color: "#FFF",
    fontSize: 16,
    fontWeight: "bold",
  },
  resultContainer: {
    marginTop: 25,
    alignItems: "center",
  },
  result: {
    fontSize: 22,
    fontWeight: "bold",
    color: "#1E40AF",
  },
  category: {
    fontSize: 18,
    marginTop: 8,
    color: "#475569",
  },
  dica: {
    fontSize: 16,
    textAlign: "center",
    color: "#64748B",
    marginTop: 10,
    paddingHorizontal: 20,
  },
});
